          && isTrue(analyzer.subtype(st2, st1))
          && !analyzer.definitelyExcludes(c1.arrow.getDomain, c2.arrow.getDomain)) {
          pruned += c2
        }
      }
    }

    // Remove the pruned candidates.
    candidates.filterNot(c => pruned.contains(c))
